add_filter( 'posts_search', 'perfectpixel_admin_search_products_by_meta', 20, 2 );

function perfectpixel_admin_search_products_by_meta( $search, $query ) {
	global $wpdb, $pagenow;
	if ( ! is_admin() || 'edit.php' !== $pagenow || 'product' !== $query->get( 'post_type' ) || ! $query->is_main_query() || '' === $search ) {
		return $search;
	}
	$term = trim( (string) $query->get( 's' ) );
	$key  = sanitize_text_field( '{{admin_search_meta_key}}' );
	if ( '' === $term || '' === $key ) {
		return $search;
	}
	$ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT DISTINCT IF( p.post_parent > 0, p.post_parent, p.ID ) FROM {$wpdb->postmeta} m
			INNER JOIN {$wpdb->posts} p ON p.ID = m.post_id
			WHERE m.meta_key = %s AND m.meta_value LIKE %s LIMIT 500",
			$key,
			'%' . $wpdb->esc_like( $term ) . '%'
		)
	);
	$ids = array_filter( array_map( 'intval', $ids ) );
	if ( ! $ids || 0 !== strpos( ltrim( $search ), 'AND' ) ) {
		return $search;
	}
	return ' AND ( ' . substr( ltrim( $search ), 3 ) . " OR {$wpdb->posts}.ID IN (" . implode( ',', $ids ) . ') ) ';
}
